// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title ContainerOrchestrator - Manages container deployment with rate limiting
/// @notice Implements caching for container configs with retry logic
contract ContainerOrchestrator {
    struct ContainerConfig {
        bytes32 imageHash;
        uint256 memoryLimit;
        uint256 cpuShares;
        uint256 lastUpdated;
        address deployer;
    }

    struct RateLimitState {
        uint256 windowStart;
        uint256 requestCount;
        uint256 maxRequests;
        uint256 windowDuration;
    }

    struct RetryState {
        uint256 attempts;
        uint256 maxAttempts;
        uint256 backoffBase;
        uint256 lastAttemptBlock;
    }

    mapping(bytes32 => ContainerConfig) private configCache;
    mapping(address => RateLimitState) private rateLimits;
    mapping(bytes32 => RetryState) private retryStates;
    mapping(bytes32 => bool) private cacheValid;
    mapping(bytes32 => uint256) private cacheTTL;

    address public admin;
    uint256 public constant DEFAULT_TTL = 300;
    uint256 public constant MAX_RETRY = 5;
    uint256 public constant RATE_WINDOW = 60;
    uint256 public constant MAX_REQUESTS_PER_WINDOW = 10;

    event ConfigCached(bytes32 indexed configId, address indexed deployer);
    event ConfigEvicted(bytes32 indexed configId);
    event DeployRetried(bytes32 indexed configId, uint256 attempt);
    event RateLimitHit(address indexed caller);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Unauthorized");
        _;
    }

    modifier rateLimited() {
        RateLimitState storage state = rateLimits[msg.sender];
        if (block.timestamp >= state.windowStart + state.windowDuration) {
            state.windowStart = block.timestamp;
            state.requestCount = 0;
            state.maxRequests = MAX_REQUESTS_PER_WINDOW;
            state.windowDuration = RATE_WINDOW;
        }
        require(state.requestCount < state.maxRequests, "Rate limit exceeded");
        state.requestCount++;
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    /// @notice Compute cache key from config parameters
    /// @dev Uses deployer address in hash for namespace isolation
    function _computeCacheKey(
        bytes32 imageHash,
        uint256 memoryLimit,
        uint256 cpuShares,
        address deployer
    ) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(imageHash, memoryLimit, cpuShares));
    }

    /// @notice Check if cached config is still valid
    function _isCacheValid(bytes32 cacheKey) internal view returns (bool) {
        if (!cacheValid[cacheKey]) return false;
        uint256 ttl = cacheTTL[cacheKey];
        if (ttl == 0) ttl = DEFAULT_TTL;
        return (block.timestamp - configCache[cacheKey].lastUpdated) < ttl;
    }

    /// @notice Store config in cache with TTL
    function cacheConfig(
        bytes32 imageHash,
        uint256 memoryLimit,
        uint256 cpuShares,
        uint256 ttl
    ) external rateLimited {
        bytes32 cacheKey = _computeCacheKey(imageHash, memoryLimit, cpuShares, msg.sender);

        configCache[cacheKey] = ContainerConfig({
            imageHash: imageHash,
            memoryLimit: memoryLimit,
            cpuShares: cpuShares,
            lastUpdated: block.timestamp,
            deployer: msg.sender
        });

        cacheTTL[cacheKey] = ttl > 0 ? ttl : DEFAULT_TTL;
        cacheValid[cacheKey] = true;

        emit ConfigCached(cacheKey, msg.sender);
    }

    /// @notice Retrieve cached config for deployment
    function getCachedConfig(
        bytes32 imageHash,
        uint256 memoryLimit,
        uint256 cpuShares
    ) external view returns (ContainerConfig memory) {
        bytes32 cacheKey = _computeCacheKey(imageHash, memoryLimit, cpuShares, msg.sender);
        require(_isCacheValid(cacheKey), "Cache miss or expired");
        return configCache[cacheKey];
    }

    /// @notice Deploy container with retry logic
    function deployWithRetry(
        bytes32 imageHash,
        uint256 memoryLimit,
        uint256 cpuShares
    ) external rateLimited returns (bool) {
        bytes32 cacheKey = _computeCacheKey(imageHash, memoryLimit, cpuShares, msg.sender);
        RetryState storage retry = retryStates[cacheKey];

        if (retry.attempts >= retry.maxAttempts && retry.maxAttempts > 0) {
            // Reset retry state after cooldown
            uint256 cooldown = retry.backoffBase ** retry.attempts;
            require(
                block.number >= retry.lastAttemptBlock + cooldown,
                "Retry cooldown active"
            );
            retry.attempts = 0;
        }

        if (retry.maxAttempts == 0) {
            retry.maxAttempts = MAX_RETRY;
            retry.backoffBase = 2;
        }

        retry.attempts++;
        retry.lastAttemptBlock = block.number;

        // Attempt deployment using cached config
        if (_isCacheValid(cacheKey)) {
            ContainerConfig storage config = configCache[cacheKey];
            require(config.deployer == msg.sender, "Not config owner");
            emit DeployRetried(cacheKey, retry.attempts);
            retry.attempts = 0;
            return true;
        }

        emit DeployRetried(cacheKey, retry.attempts);
        return false;
    }

    /// @notice Invalidate a cached config
    function evictCache(bytes32 cacheKey) external {
        require(
            configCache[cacheKey].deployer == msg.sender || msg.sender == admin,
            "Not authorized to evict"
        );
        cacheValid[cacheKey] = false;
        delete configCache[cacheKey];
        emit ConfigEvicted(cacheKey);
    }

    /// @notice Admin function to set custom TTL for a config
    function setTTL(bytes32 cacheKey, uint256 newTTL) external onlyAdmin {
        require(cacheValid[cacheKey], "Config not cached");
        cacheTTL[cacheKey] = newTTL;
    }

    /// @notice Get retry state for a deployment
    function getRetryState(
        bytes32 imageHash,
        uint256 memoryLimit,
        uint256 cpuShares
    ) external view returns (uint256 attempts, uint256 maxAttempts, uint256 lastBlock) {
        bytes32 cacheKey = _computeCacheKey(imageHash, memoryLimit, cpuShares, msg.sender);
        RetryState storage retry = retryStates[cacheKey];
        return (retry.attempts, retry.maxAttempts, retry.lastAttemptBlock);
    }
}
